using System.Diagnostics;
using NexaStation.Core;
using NexaStation.Domain;
using NexaStation.Infrastructure.Persistence;
using NexaStation.Providers.Gallery.Metadata;
using NexaStation.Providers.Gallery.Scanning;
using NexaStation.Providers.Gallery.Sources;
using NexaStation.Providers.Gallery.Thumbnails;
using NexaStation.Providers.Gallery.Validation;
using NexaStation.Providers.Gallery.Watching;
using Xunit;

namespace NexaStation.Providers.Gallery.Tests;

public sealed class GalleryProviderTests
{
    [Theory]
    [InlineData("photo.JPG",GalleryMediaType.Image)]
    [InlineData("animation.gif",GalleryMediaType.AnimatedImage)]
    [InlineData("movie.MKV",GalleryMediaType.Video)]
    [InlineData("clip.webm",GalleryMediaType.Video)]
    public async Task ScannerMatchesSupportedExtensionsCaseInsensitively(string name,GalleryMediaType expected)
    { using TempFolder folder=new();File.WriteAllBytes(Path.Combine(folder.Path,name),[0]);GallerySourceScanResult result=await new GallerySourceScanner().ScanAsync(Source(folder.Path));Assert.True(result.IsComplete);Assert.Single(result.Candidates);Assert.Equal(expected,result.Candidates[0].MediaType); }

    [Fact] public async Task ScannerIgnoresUnsupportedFiles(){using TempFolder folder=new();File.WriteAllText(Path.Combine(folder.Path,"notes.txt"),"not media");Assert.Empty((await new GallerySourceScanner().ScanAsync(Source(folder.Path))).Candidates);}
    [Fact] public async Task ScannerRespectsSubfolderSetting(){using TempFolder folder=new();Directory.CreateDirectory(Path.Combine(folder.Path,"nested"));File.WriteAllBytes(Path.Combine(folder.Path,"nested","image.png"),[0]);Assert.Empty((await new GallerySourceScanner().ScanAsync(Source(folder.Path) with{IncludeSubfolders=false})).Candidates);Assert.Single((await new GallerySourceScanner().ScanAsync(Source(folder.Path))).Candidates);}
    [Fact] public async Task ScannerRespectsImageAndVideoSettings(){using TempFolder folder=new();File.WriteAllBytes(Path.Combine(folder.Path,"a.png"),[0]);File.WriteAllBytes(Path.Combine(folder.Path,"b.mp4"),[0]);GallerySourceScanResult images=await new GallerySourceScanner().ScanAsync(Source(folder.Path) with{IncludeVideos=false});GallerySourceScanResult videos=await new GallerySourceScanner().ScanAsync(Source(folder.Path) with{IncludeImages=false});Assert.Single(images.Candidates);Assert.Equal(GalleryMediaType.Image,images.Candidates[0].MediaType);Assert.Single(videos.Candidates);Assert.Equal(GalleryMediaType.Video,videos.Candidates[0].MediaType);}
    [Fact] public async Task ScannerSkipsHiddenFilesByDefault(){using TempFolder folder=new();string path=Path.Combine(folder.Path,"hidden.png");File.WriteAllBytes(path,[0]);File.SetAttributes(path,FileAttributes.Hidden);Assert.Empty((await new GallerySourceScanner().ScanAsync(Source(folder.Path))).Candidates);Assert.Single((await new GallerySourceScanner().ScanAsync(Source(folder.Path) with{IncludeHiddenFiles=true})).Candidates);}
    [Fact] public async Task ScannerReportsUnavailableRootWithoutInventingDeletion(){using TempFolder folder=new();string missing=Path.Combine(folder.Path,"missing");GallerySourceScanResult result=await new GallerySourceScanner().ScanAsync(Source(missing));Assert.False(result.RootAvailable);Assert.False(result.IsComplete);Assert.NotEmpty(result.Warnings);}
    [Fact] public async Task ScannerSupportsCancellation(){using TempFolder folder=new();using CancellationTokenSource cancel=new();cancel.Cancel();await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>new GallerySourceScanner().ScanAsync(Source(folder.Path),cancel.Token));}

    [Fact] public async Task ImageInspectorReadsSyntheticPngDimensionsWithoutGps(){using TempFolder folder=new();string path=Path.Combine(folder.Path,"pixel.png");await File.WriteAllBytesAsync(path,Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII="));FileInfo info=new(path);GalleryMediaCandidate candidate=new(path,path,"pixel.png",".png",folder.Path,info.Length,info.CreationTimeUtc,info.LastWriteTimeUtc,GalleryMediaType.Image);GalleryMediaInspectionResult result=await new WindowsGalleryMediaInspector().InspectAsync(new(candidate,true));Assert.Equal(1,result.Width);Assert.Equal(1,result.Height);Assert.Null(result.CameraModel);}
    [Fact] public async Task CorruptImageReturnsUnsupportedStateInsteadOfThrowing(){using TempFolder folder=new();string path=Path.Combine(folder.Path,"bad.jpg");await File.WriteAllTextAsync(path,"not an image");FileInfo info=new(path);GalleryMediaInspectionResult result=await new WindowsGalleryMediaInspector().InspectAsync(new(new(path,path,"bad.jpg",".jpg",folder.Path,info.Length,info.CreationTimeUtc,info.LastWriteTimeUtc,GalleryMediaType.Image)));Assert.True(result.UnsupportedCodec);Assert.NotNull(result.Warning);}

    [Fact] public void PathPolicyRejectsEmptyAndClassifiesConservatively(){Assert.Throws<ArgumentException>(()=>GalleryPathPolicy.NormalizeFolder(" "));Assert.Equal(GalleryMediaType.Unknown,GalleryPathPolicy.Classify(".exe"));Assert.Equal(GalleryMediaType.Image,GalleryPathPolicy.Classify(".heic"));}
    [Fact] public void MemoryCacheIsBoundedAndLeastRecentlyUsed(){BoundedThumbnailMemoryCache cache=new(5);cache.Put("a",[1,2,3]);cache.Put("b",[4,5,6]);Assert.False(cache.TryGet("a",out _));Assert.True(cache.TryGet("b",out byte[]? value));Assert.Equal(3,value!.Length);Assert.True(cache.Bytes<=5);}
    [Fact] public async Task DebounceCombinesBurstIntoOneRefresh(){int calls=0;await using DebouncedGalleryChangeBuffer buffer=new(TimeSpan.FromMilliseconds(30));buffer.Start((_,_)=>{Interlocked.Increment(ref calls);return Task.CompletedTask;},CancellationToken.None);buffer.Signal("source");buffer.Signal("source");buffer.Signal("source");await Task.Delay(120);Assert.Equal(1,calls);}

    [Fact] public async Task GallerySchemaMigrationsExistAndInitialize(){await using TestDatabase db=await TestDatabase.CreateAsync();Assert.Equal(5,await db.ScalarAsync("SELECT COUNT(*) FROM SchemaMigrations WHERE Version BETWEEN 16 AND 20;"));Assert.Equal(1,await db.ScalarAsync("SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='GalleryMediaItems';"));}
    [Fact] public async Task ExactAndOverlappingSourcesAreDetected(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);using TempFolder folder=new();GallerySource parent=Source(folder.Path);await persistence.AddSourceAsync(parent);Assert.Equal(GallerySourceOverlapKind.Exact,(await persistence.FindSourceOverlapsAsync(folder.Path)).Single().Kind);string child=Directory.CreateDirectory(Path.Combine(folder.Path,"child")).FullName;Assert.Equal(GallerySourceOverlapKind.ExistingParent,(await persistence.FindSourceOverlapsAsync(child)).Single().Kind);}
    [Fact] public async Task ExplicitApprovalIsRequired(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);GalleryLibraryService service=new(persistence,new GallerySourceScanner(),new WindowsGalleryMediaInspector(),new NoopThumbnails());using TempFolder folder=new();await Assert.ThrowsAsync<InvalidOperationException>(()=>service.AddSourceAsync(Source(folder.Path),false,false));}
    [Fact] public async Task SuccessfulRefreshAddsAndLaterMarksMissing(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);using TempFolder folder=new();GallerySource source=Source(folder.Path);await persistence.AddSourceAsync(source);GalleryMediaInspectionResult item=Inspection(folder.Path,"a.png",10);GallerySourceScanResult first=Scan(source,[item.Candidate]);GalleryRefreshResult added=await persistence.ApplyScanAsync(first,[item]);Assert.Equal(1,added.Added);GalleryRefreshResult missing=await persistence.ApplyScanAsync(Scan(source,[]),[]);Assert.Equal(1,missing.Missing);Assert.Empty(await persistence.QueryAsync(new(SourceId:source.Id)));Assert.Single(await persistence.QueryAsync(new(SourceId:source.Id,IncludeUnavailable:true)));}
    [Fact] public async Task FailedRefreshPreservesAvailability(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);using TempFolder folder=new();GallerySource source=Source(folder.Path);await persistence.AddSourceAsync(source);GalleryMediaInspectionResult item=Inspection(folder.Path,"a.png",10);await persistence.ApplyScanAsync(Scan(source,[item.Candidate]),[item]);GallerySourceScanResult failed=new(source,[],[],["access denied"],false,false,true,DateTime.UtcNow,DateTime.UtcNow);GalleryRefreshResult result=await persistence.ApplyScanAsync(failed,[]);Assert.False(result.Applied);Assert.Single(await persistence.QueryAsync(new(SourceId:source.Id)));}
    [Fact] public async Task IncrementalRefreshPreservesFavoritesAndAlbums(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);using TempFolder folder=new();GallerySource source=Source(folder.Path);await persistence.AddSourceAsync(source);GalleryMediaInspectionResult item=Inspection(folder.Path,"a.png",10);await persistence.ApplyScanAsync(Scan(source,[item.Candidate]),[item]);GalleryMediaItem media=(await persistence.QueryAsync(new())).Single();await persistence.SetFavoriteAsync(media.Id,true);DateTime now=DateTime.UtcNow;GalleryAlbum album=new("album","Test",null,GalleryAlbumType.Manual,media.Id,null,0,now,now);await persistence.SaveAlbumAsync(album);await persistence.AddAlbumItemAsync(new(album.Id,media.Id,0,now));await persistence.ApplyScanAsync(Scan(source,[item.Candidate]),[item]);Assert.True((await persistence.GetMediaItemAsync(media.Id))!.Favorite);Assert.Single(await persistence.QueryAsync(new(AlbumId:album.Id)));}
    [Fact] public async Task PrivateSourcesAreExcludedFromHome(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);using TempFolder folder=new();GallerySource source=Source(folder.Path) with{PrivacyLevel=GalleryPrivacyLevel.Private,ShowOnHome=false};await persistence.AddSourceAsync(source);GalleryMediaInspectionResult item=Inspection(folder.Path,"a.png",10);await persistence.ApplyScanAsync(Scan(source,[item.Candidate]),[item]);Assert.Empty(await persistence.QueryAsync(new(HomePreviewOnly:true)));Assert.Single(await persistence.QueryAsync(new(IncludePrivate:true)));}
    [Fact] public async Task RelinkPreservesIdentityAndFavorite(){await using TestDatabase db=await TestDatabase.CreateAsync();SqliteGalleryPersistence persistence=new(db.Factory);using TempFolder folder=new();GallerySource source=Source(folder.Path);await persistence.AddSourceAsync(source);GalleryMediaInspectionResult item=Inspection(folder.Path,"a.png",10);await persistence.ApplyScanAsync(Scan(source,[item.Candidate]),[item]);GalleryMediaItem media=(await persistence.QueryAsync(new())).Single();await persistence.SetFavoriteAsync(media.Id,true);string replacement=Path.Combine(folder.Path,"replacement.png");await persistence.RelinkMediaAsync(media.Id,replacement,replacement,20,DateTime.UtcNow);GalleryMediaItem reloaded=(await persistence.GetMediaItemAsync(media.Id))!;Assert.Equal(media.Id,reloaded.Id);Assert.True(reloaded.Favorite);Assert.Equal(replacement,reloaded.FilePath);}
    [Fact] public async Task TenThousandFileEnumerationStreamsWithinBudget(){using TempFolder folder=new();for(int index=0;index<10000;index++)File.WriteAllBytes(Path.Combine(folder.Path,$"{index}.jpg"),[]);Stopwatch timer=Stopwatch.StartNew();GallerySourceScanResult result=await new GallerySourceScanner().ScanAsync(Source(folder.Path));timer.Stop();Assert.Equal(10000,result.Candidates.Count);Assert.True(timer.Elapsed<TimeSpan.FromSeconds(20),$"10,000-file scan took {timer.Elapsed}.");}

    private static GallerySource Source(string path)=>new(){Id=Guid.NewGuid().ToString("N"),Name="Synthetic",FolderPath=path,NormalizedFolderPath=path,SourceKind=GallerySourceKind.Photos,CreatedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow};
    private static GalleryMediaInspectionResult Inspection(string root,string name,long size){string path=Path.Combine(root,name);DateTime now=DateTime.UtcNow;return new(new(path,path,name,Path.GetExtension(name),root,size,now,now,GalleryMediaType.Image),640,480);}
    private static GallerySourceScanResult Scan(GallerySource source,IReadOnlyList<GalleryMediaCandidate> candidates){DateTime now=DateTime.UtcNow;return new(source,candidates,[],[],true,false,true,now,now);}
    private sealed class TempFolder : IDisposable{public TempFolder(){Path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"NexaStationGalleryTests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path);}public string Path{get;}public void Dispose(){if(Directory.Exists(Path))Directory.Delete(Path,true);}}
    private sealed class NoopLogger:IAppLogger{public void Information(string eventName,string message,IReadOnlyDictionary<string,object?>? properties=null){}public void LogError(string eventName,string message,Exception? exception=null,IReadOnlyDictionary<string,object?>? properties=null){}}
    private sealed class NoopThumbnails:IGalleryThumbnailService{public Task ClearCacheAsync(CancellationToken cancellationToken=default)=>Task.CompletedTask;public Task<GalleryThumbnailCacheStats> GetCacheStatsAsync(CancellationToken cancellationToken=default)=>Task.FromResult(new GalleryThumbnailCacheStats(0,0,0,0));public Task<GalleryThumbnailResult> GetOrCreateAsync(GalleryThumbnailRequest request,CancellationToken cancellationToken=default)=>Task.FromResult(new GalleryThumbnailResult(false,null,0,0,false,true));public Task InvalidateAsync(string galleryMediaItemId,CancellationToken cancellationToken=default)=>Task.CompletedTask;}
    private sealed class TestDatabase : IAsyncDisposable{private readonly string _root;private TestDatabase(string root,SqliteConnectionFactory factory){_root=root;Factory=factory;}public SqliteConnectionFactory Factory{get;}public static async Task<TestDatabase> CreateAsync(){string root=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"NexaStationGalleryDb",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);SqliteConnectionFactory factory=new(System.IO.Path.Combine(root,"test.db"));await new DatabaseInitializer(factory,new NoopLogger()).InitializeAsync();return new(root,factory);}public async Task<long> ScalarAsync(string sql){await using Microsoft.Data.Sqlite.SqliteConnection connection=await Factory.OpenAsync();await using Microsoft.Data.Sqlite.SqliteCommand command=connection.CreateCommand();command.CommandText=sql;return Convert.ToInt64(await command.ExecuteScalarAsync(),System.Globalization.CultureInfo.InvariantCulture);}public ValueTask DisposeAsync(){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();try{if(Directory.Exists(_root))Directory.Delete(_root,true);}catch(IOException){}return ValueTask.CompletedTask;}}
}
